#!/usr/bin/env python3
# ============================================================
#  gen_tests.py -- compile the fc32e1s_nano_fpga C tests to assembly
#
#  For every src/*.c and every optimisation level in OPTS, writes
#  assembly/<name>_<opt>.S (generated, gitignored): the compiler output plus
#      #define C_EXPECT <value of the "// EXPECT: <value>" line of the source>
#      #include "../src/crt.S"   start-up, checks main()'s return value
#      #include "../src/rt.S"    __mulsi3 / div / mod on a0..a2 (+ ra) only
#  run_spike.sh runs this first, then assembles, links and register-scans the
#  result like any other test.
#
#  The 6-register convention (x0, ra, sp, a0..a2) comes from the -ffixed-*
#  flags below. They cannot stop GCC from passing a 4th integer argument in a3:
#  keep functions at <= 3 integer arguments (run_spike.sh's register scan
#  catches a violation).
# ============================================================
import glob
import os
import re
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "assembly")
CC = os.environ.get("CC", "riscv64-unknown-elf-gcc")

OPTS = ["O2", "Os"]
CFLAGS = ["-march=rv32e", "-mabi=ilp32e", "-ffreestanding", "-fno-builtin",
          "-fno-tree-loop-distribute-patterns",       # no memset/memcpy calls invented
          "-fno-ident", "-fno-asynchronous-unwind-tables",
          "-ffixed-gp", "-ffixed-tp", "-ffixed-t0", "-ffixed-t1", "-ffixed-t2",
          "-ffixed-s0", "-ffixed-s1", "-ffixed-a3", "-ffixed-a4", "-ffixed-a5"]


def main():
    os.makedirs(OUT, exist_ok=True)
    for f in glob.glob(os.path.join(OUT, "*.S")):
        os.remove(f)
    for src in sorted(glob.glob(os.path.join(HERE, "src", "*.c"))):
        name = os.path.splitext(os.path.basename(src))[0]
        m = re.search(r"^//\s*EXPECT:\s*(\S+)", open(src).read(), re.M)
        if not m:
            sys.exit("%s: no '// EXPECT: <value>' line" % src)
        for opt in OPTS:
            asm = subprocess.run([CC, "-S", "-" + opt] + CFLAGS + [src, "-o", "-"],
                                 check=True, capture_output=True, text=True).stdout
            with open(os.path.join(OUT, "%s_%s.S" % (name, opt)), "w", newline="\n") as f:
                f.write("// generated by gen_tests.py from src/%s.c (-%s) -- do not edit\n" % (name, opt))
                f.write("#define C_EXPECT %s\n" % m.group(1))
                f.write(asm)
                f.write('\n#include "../src/crt.S"\n#include "../src/rt.S"\n')


if __name__ == "__main__":
    main()
